mapper.select:
SELECT COUNT(*)
  FROM TB_FAVORITE
 WHERE MEMBER_NO = #{memberNo}
   AND TARGET_ID = #{targetId}


   AND FAV_TYPE IN ('LODGE', 'STAY')


   AND FAV_TYPE = #{favType}

mapper.delete:
DELETE FROM TB_FAVORITE
 WHERE MEMBER_NO = #{memberNo}
   AND TARGET_ID = #{targetId}


   AND FAV_TYPE IN ('LODGE', 'STAY')


   AND FAV_TYPE = #{favType}
